import fs from 'node:fs';
import {createPublicClient,http} from '../enclave/node_modules/viem/_esm/index.js';
import {fetchPackage,bootstrapIntent} from '../enclave/sdk/bootstrap/package.mjs';
const root=new URL('./',import.meta.url),read=n=>JSON.parse(fs.readFileSync(new URL(n,root)));
const id=read('chain-state.json').id,derived=read('derived.json');
const ledger='0xb1783b61e1fdee6a6163dc3cdac27bf32e7d117b';
const abi=JSON.parse(fs.readFileSync(new URL('../enclave/contracts/EnclaveDeployments.abi.json',root)));
const urls=['https://base-rpc.publicnode.com','https://base.drpc.org','https://mainnet.base.org'];
const clients=urls.map(url=>createPublicClient({transport:http(url,{timeout:15000,retryCount:0})}));
const heads=await Promise.all(clients.map(c=>c.getBlockNumber()));const blockNumber=heads.reduce((a,b)=>a<b?a:b)-2n;
const rows=await Promise.all(clients.map(async c=>{const b=await c.getBlock({blockNumber});const d=await c.readContract({address:ledger,abi,functionName:'get',args:[id],blockNumber});return {blockHash:b.hash,timestamp:b.timestamp,d};}));
const stringify=x=>JSON.stringify(x,(_,v)=>typeof v==='bigint'?String(v):v);
if(rows.some(r=>stringify(r)!==stringify(rows[0])))throw Error('fixed-block chain disagreement');
if(Math.abs(Date.now()/1000-Number(rows[0].timestamp))>180)throw Error('stale block');
const d=rows[0].d, intent=bootstrapIntent(d.configCid);
const scope={chainId:8453,ledger,deployment:id,owner:d.owner,appRef:d.appRef,appId:derived.appId,runtimeId:derived.derive.runtimeId};
const calls=[];const p=await fetchPackage(intent,scope,{gateways:['http://127.0.0.1:1/ipfs','http://134.209.248.172:8189/ipfs','http://165.245.191.129:8189/ipfs'],allowHttpIPs:true,fetchImpl:(u,i)=>{calls.push(String(u));return fetch(u,i);}});
fs.writeFileSync(new URL('package.json',root),p.bytes);
fs.writeFileSync(new URL('package-proof.json',root),stringify({verifiedAt:new Date().toISOString(),blockNumber,blockHash:rows[0].blockHash,scope,intent,calls,bytes:p.bytes.length})+'\n');
console.log(stringify({blockNumber,packageBytes:p.bytes.length,calls}));
